def comps(g):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] not in (0,) and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<len(g) and 0<=y<len(g[0]) and (x,y) not in seen and g[x][y]==col:
                                seen.add((x,y)); q.append((x,y))
                out.append((col,len(cells),sorted(cells)))
    return out
